"""Generated bytes, not merely their upstream inputs, define exact resume."""
import json
import tempfile
import unittest
from pathlib import Path
from unittest.mock import patch

import numpy as np
import torch

from lm_config import LMExperimentConfig, LMTrainConfig
from rl_lm.cache import build_cache, cache_identity, load_cache, plan_contexts, seal_cache
from rl_lm.checkpoint import save_atomic
from rl_lm.config import RLConfig
from rl_lm.trainer import CacheContextProvider, Trainer
from tests.rl_lm import test_cache
from tests.rl_lm.test_resume import toy_config_dict
from tests.rl_lm.tiny_lm import build_tiny_model


class CacheIntegrityTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.dataset = test_cache.CacheTests().make_dataset(self.root)
        self.model = build_tiny_model()
        torch.save({'model': self.model.state_dict()}, self.root / 'model.pt')
        LMExperimentConfig(model=self.model.config, train=LMTrainConfig(data_dir=str(self.root))).save(self.root / 'config.json')
        (self.root / 'tokenizer.json').write_text('{}')
        self.identity = cache_identity(self.model, self.model.config, checkpoint_path=self.root / 'model.pt', config_path=self.root / 'config.json', tokenizer_path=self.root / 'tokenizer.json', data_dir=self.root, split='train', sampling_seed=4, backend_version='toy-v1', head_contract='bf16_linear_fp32_ce_v1', expert_chunk=64)
        self.path = self.root / 'pair' / 'train'
        self.contexts = plan_contexts(self.dataset, 8, seed=4, corpus_id='toy')
        build_cache(self.model, self.dataset, self.contexts, output_dir=self.path, identity=self.identity, dtype='float32')

    def reseal(self):
        seal_cache(self.path, self.identity, count=8, width=self.model.config.hidden_size)

    def test_every_payload_byte_is_verified(self):
        for name in ['h0.npy', 'targets.npy', 'positions.npy', 'sequence_indices.npy', 'episode_ids.jsonl', 'baseline.jsonl', 'sampling_report.json']:
            with self.subTest(name=name):
                path = self.path / name
                original = path.read_bytes()
                changed = bytearray(original)
                changed[-2] ^= 1
                path.write_bytes(changed)
                with self.assertRaisesRegex(ValueError, 'hash mismatch'):
                    load_cache(self.path, self.identity)
                path.write_bytes(original)

    def test_legacy_not_silently_certified(self):
        path = self.path / 'manifest.json'
        manifest = json.loads(path.read_text())
        del manifest['payload']
        path.write_text(json.dumps(manifest))
        with self.assertRaisesRegex(ValueError, 'rebuild'):
            load_cache(self.path, self.identity)

    def test_invalid_dtype_shape_nonfinite_and_counts(self):
        path = self.path / 'h0.npy'
        original = np.load(path).copy()
        for changed in [original.astype(np.float64), original[:2], original * np.nan]:
            np.save(path, changed)
            with self.assertRaises(ValueError):
                self.reseal()
        np.save(path, original)
        baseline = self.path / 'baseline.jsonl'
        baseline.write_text(baseline.read_text().splitlines()[0] + '\n')
        with self.assertRaisesRegex(ValueError, 'row count'):
            self.reseal()

    def test_real_resume_rejects_rehashed_replacement(self):
        config = RLConfig.from_dict(toy_config_dict(self.root / 'run'))
        provider = CacheContextProvider(load_cache(self.path, self.identity))
        trainer = Trainer(config, self.model, train_contexts=provider, device='cpu', data_identity={'controller_train': self.identity})
        checkpoint = save_atomic(self.root / 'run' / 'checkpoint_latest.pt', trainer._checkpoint_payload())
        resumed = Trainer(config, self.model, train_contexts=provider, device='cpu', data_identity={'controller_train': self.identity}, resume_path=checkpoint)
        self.assertTrue(resumed.resumed)
        targets = np.load(self.path / 'targets.npy').copy()
        targets[0] = (targets[0] + 1) % self.model.config.vocab_size
        np.save(self.path / 'targets.npy', targets)
        self.reseal()
        replaced = CacheContextProvider(load_cache(self.path, self.identity))
        with self.assertRaisesRegex(ValueError, 'data_identity'):
            Trainer(config, self.model, train_contexts=replaced, device='cpu', data_identity={'controller_train': self.identity}, resume_path=checkpoint)

    def test_failed_build_is_atomic_and_identity_not_mutated(self):
        destination = self.root / 'failed'
        identity = self.identity | {'excluded_doc_ids': set()}
        with patch('rl_lm.cache._baseline_records', side_effect=RuntimeError('interrupted')):
            with self.assertRaises(RuntimeError):
                build_cache(self.model, self.dataset, self.contexts, output_dir=destination, identity=identity, dtype='float32')
        self.assertFalse(destination.exists())
        self.assertFalse(list(self.root.glob('failed.staging-*')))
        self.assertIn('excluded_doc_ids', identity)

    def test_derived_cache_verifies_source_and_seals_single_bytes(self):
        from experiments.rl_lm_single_adapt import derive_single_cache
        from tests.rl_lm.test_single_adapt import _toy_config
        config = _toy_config(self.root / 'adapt')
        config.data['backbone'].update(checkpoint_path=str(self.root / 'model.pt'), config_path=str(self.root / 'config.json'))
        config.data['data'].update(corpus_dir=str(self.root), tokenizer_path=str(self.root / 'tokenizer.json'), pair_cache_root=str(self.root / 'pair'), cache_root=str(self.root / 'single'), sampling_seed=4, train_states=8, train_split='train')
        output = derive_single_cache(config, self.model, 'train', torch.device('cpu'))
        cache = load_cache(output, {})
        self.assertIn('single_teacher_ce', cache['baseline'][0])
        self.assertIn('content_sha256', cache['verified_identity'])
        # Source mutation between verification and copy must not be certified.
        import shutil
        original_copy = shutil.copy2
        config.data['data']['cache_root'] = str(self.root / 'single-race')
        def changing_copy(source, destination):
            if Path(source).name == 'targets.npy':
                changed = np.load(source).copy()
                changed[0] += 1
                np.save(source, changed)
            return original_copy(source, destination)
        with patch('experiments.rl_lm_single_adapt.shutil.copy2', side_effect=changing_copy):
            with self.assertRaisesRegex(ValueError, 'changed during derivation'):
                derive_single_cache(config, self.model, 'train', torch.device('cpu'))
        self.assertFalse((self.root / 'single-race' / 'train').exists())
        targets = np.load(self.path / 'targets.npy').copy()
        targets[0] += 1
        np.save(self.path / 'targets.npy', targets)
        with self.assertRaisesRegex(ValueError, 'hash mismatch'):
            derive_single_cache(config, self.model, 'train', torch.device('cpu'))

    def test_optimized_prefix_cannot_be_certified(self):
        from model.top2 import set_top2_dispatch_backend
        set_top2_dispatch_backend(self.model, "merged")
        with self.assertRaisesRegex(ValueError, "profiling-only"):
            build_cache(self.model, self.dataset, self.contexts, output_dir=self.root / 'optimized', identity=self.identity)

    def test_single_real_resume_rejects_rehashed_cache(self):
        from experiments.rl_lm_single_train import SingleCacheContextProvider, SingleTrainer
        from rl_lm.single_config import SingleRLConfig
        from tests.rl_lm.test_single_rloo import toy_config_dict as single_config
        config = SingleRLConfig(single_config(self.root / 'single-run'))
        cache = load_cache(self.path, self.identity)
        ref = np.asarray([row['canonical_ce'] for row in cache['baseline']], dtype=np.float32)
        provider = SingleCacheContextProvider(cache, ref)
        trainer = SingleTrainer(config, self.model, train_contexts=provider, device='cpu')
        path = save_atomic(self.root / 'single-run' / 'checkpoint_latest.pt', trainer._checkpoint_payload())
        SingleTrainer(config, self.model, train_contexts=provider, device='cpu', resume_path=path)
        targets = np.load(self.path / 'targets.npy').copy()
        targets[0] += 1
        np.save(self.path / 'targets.npy', targets)
        self.reseal()
        changed = SingleCacheContextProvider(load_cache(self.path, self.identity), ref)
        with self.assertRaisesRegex(ValueError, 'data_identity'):
            SingleTrainer(config, self.model, train_contexts=changed, device='cpu', resume_path=path)

    def test_adaptation_resume_rejects_rehashed_cache(self):
        from experiments.rl_lm_single_adapt import AdaptTrainer
        from tests.rl_lm.test_single_adapt import _toy_config
        run = self.root / 'adapt-run'
        config = _toy_config(run)
        cache = load_cache(self.path, self.identity)
        trainer = AdaptTrainer(config, self.model, train_cache=cache, device=torch.device('cpu'), run_dir=run)
        path = trainer._save()
        AdaptTrainer(config, self.model, train_cache=cache, device=torch.device('cpu'), run_dir=run, resume_path=path)
        targets = np.load(self.path / 'targets.npy').copy()
        targets[0] += 1
        np.save(self.path / 'targets.npy', targets)
        self.reseal()
        with self.assertRaisesRegex(ValueError, 'verified_train_cache'):
            AdaptTrainer(config, self.model, train_cache=load_cache(self.path, self.identity), device=torch.device('cpu'), run_dir=run, resume_path=path)

    def test_reference_ce_artifact_validation_and_real_resume(self):
        from experiments.rl_lm_single_train import (SingleCacheContextProvider, SingleTrainer,
            load_reference_ce, reference_ce_artifact, reference_ce_payload_identity)
        from rl_lm.single_config import SingleRLConfig
        from tests.rl_lm.test_single_rloo import toy_config_dict as single_config
        cache = load_cache(self.path, self.identity)
        reference = np.ones(8, dtype=np.float64)
        content, meta = reference_ce_artifact(reference, {'source': 'fixed'}, 8)
        path = self.root / 'reference_ce.npy'
        path.write_bytes(content)
        loaded = load_reference_ce(path, meta, {'source': 'fixed'}, 8)
        np.testing.assert_array_equal(loaded, reference)
        for invalid in (reference[:3], reference.astype(np.int64), reference * np.nan):
            with self.assertRaises(ValueError):
                reference_ce_payload_identity(invalid, 8)
        with self.assertRaisesRegex(ValueError, 'legacy'):
            load_reference_ce(path, {'identity': {'source': 'fixed'}}, {'source': 'fixed'}, 8)
        changed = reference.copy()
        changed[0] = 2
        changed_bytes, changed_meta = reference_ce_artifact(changed, {'source': 'fixed'}, 8)
        path.write_bytes(changed_bytes)
        with self.assertRaisesRegex(ValueError, 'file hash'):
            load_reference_ce(path, meta, {'source': 'fixed'}, 8)
        config = SingleRLConfig(single_config(self.root / 'reference-run'))
        trainer = SingleTrainer(config, self.model, train_contexts=SingleCacheContextProvider(cache, reference), device='cpu')
        checkpoint = save_atomic(self.root / 'reference-run' / 'checkpoint_latest.pt', trainer._checkpoint_payload())
        SingleTrainer(config, self.model, train_contexts=SingleCacheContextProvider(cache, reference), device='cpu', resume_path=checkpoint)
        rehashed = load_reference_ce(path, changed_meta, {'source': 'fixed'}, 8)
        with self.assertRaisesRegex(ValueError, 'data_identity'):
            SingleTrainer(config, self.model, train_contexts=SingleCacheContextProvider(cache, rehashed), device='cpu', resume_path=checkpoint)
